insert into public.comentarios (id_comentario, fecha, id_cliente, canal, calificacion, comentario, sentimiento, subcategoria) values
  ('K001', '2026-06-20', 'C9041', 'Encuesta de cancelación', 3, 'Mi hermana sí hizo el plan guiado de 4 semanas y le encantó. A mí nunca me apareció esa opción.', 'Negativo', 'Onboarding y acompañamiento'),
  ('K002', '2026-09-18', null, 'Google Play', 2, 'Pedí que me mantuvieran el precio un mes más mientras decidía y me dijeron que no era posible.', 'Negativo', 'Precio y promoción'),
  ('K003', '2025-12-16', 'C0998', 'Encuesta de cancelación', 2, 'Abrí la app dos veces y no entendí cuál rutina era para principiantes.', 'Negativo', 'Onboarding y acompañamiento'),
  ('K004', '2026-05-20', 'C1086', 'Chat de soporte', null, 'No encuentro el botón de cancelar por ningún lado.', 'Negativo', 'Cancelación y pausa'),
  ('K005', '2026-08-06', 'C1114', 'Chat de soporte', null, 'Llevo dos semanas sin poder entrenar porque el video se queda congelado. Escribí a soporte y me dijeron que borrara caché, no sirvió.', 'Negativo', 'Estabilidad técnica'),
  ('K006', '2026-07-21', 'C1093', 'Encuesta de cancelación', 2, 'Cancelé cuando vi el cobro en la tarjeta. Si me hubieran avisado antes tal vez me quedaba.', 'Negativo', 'Cobros y avisos'),
  ('K007', '2026-07-16', null, 'Google Play', 4, 'Deberían tener un plan familiar, en mi casa somos tres usándola con la misma cuenta.', 'Negativo', 'Contenido y funcionalidades'),
  ('K008', '2026-03-22', null, 'Instagram', null, 'Solo quería pausar un mes por un viaje y la única opción era cancelar todo.', 'Negativo', 'Cancelación y pausa'),
  ('K009', '2026-07-25', 'C1294', 'Encuesta de cancelación', 2, 'Muy cara para el contenido que hay.', 'Negativo', 'Precio y promoción'),
  ('K010', '2026-05-06', 'C1122', 'Chat de soporte', null, 'Buena variedad de clases: fuerza, yoga, baile.', 'Positivo', 'Contenido y funcionalidades'),
  ('K011', '2026-07-26', null, 'Instagram', null, 'Llevo un año entrenando con la app y me siento con mucha más energía.', 'Positivo', 'Resultados y hábito'),
  ('K012', '2026-07-04', null, 'Google Play', 2, 'Perdí mi racha de 60 días porque la app no registró mis clases de esta semana, se cerraba antes de terminar.', 'Negativo', 'Estabilidad técnica'),
  ('K013', '2026-07-29', null, 'Instagram', null, 'El chat de soporte se demora horas en responder.', 'Negativo', 'Soporte al cliente'),
  ('K014', '2026-09-08', 'C1212', 'Chat de soporte', null, 'Pésima la última actualización. Antes le ponía 5 estrellas.', 'Negativo', 'Estabilidad técnica'),
  ('K015', '2026-09-13', null, 'Google Play', 3, '¿Van a aceptar pago por Nequi o PSE? No tengo tarjeta de crédito.', 'Negativo', 'Medios de pago'),
  ('K016', '2026-07-12', null, 'Instagram', null, 'Pagué el plan anual y ha sido la mejor decisión, sale mucho más barato.', 'Positivo', 'Precio y promoción'),
  ('K017', '2026-08-17', null, 'Instagram', null, 'Las clases de la profe Carolina son lo mejor. Llevo 8 meses y no la cambio.', 'Positivo', 'Contenido y funcionalidades'),
  ('K018', '2026-07-20', null, 'Google Play', 4, 'Sería chévere poder descargar las clases para verlas sin internet.', 'Negativo', 'Contenido y funcionalidades'),
  ('K019', '2026-04-27', 'C1179', 'Chat de soporte', null, 'El plan guiado de 4 semanas me cambió la rutina. Súper recomendado.', 'Positivo', 'Resultados y hábito'),
  ('K020', '2026-09-06', null, 'Instagram', null, 'Faltan clases para adultos mayores, quería inscribir a mi mamá.', 'Negativo', 'Contenido y funcionalidades'),
  ('K021', '2026-01-04', null, 'Google Play', 3, 'Nunca hice el test inicial porque es muy largo, entonces me recomendaba cosas muy avanzadas.', 'Negativo', 'Onboarding y acompañamiento'),
  ('K022', '2026-02-13', 'C1224', 'Encuesta de cancelación', 3, '¿No tienen un plan intermedio? El salto de precio después de los 3 meses es muy fuerte.', 'Negativo', 'Precio y promoción'),
  ('K023', '2026-07-26', null, 'Google Play', 1, 'Desde la actualización de julio la app se me cierra sola en la mitad de la clase. Tengo un Samsung y antes funcionaba perfecto.', 'Negativo', 'Estabilidad técnica'),
  ('K024', '2026-06-05', null, 'Google Play', 1, 'La primera clase que me salió era de nivel avanzado y no pude seguirla. No volví.', 'Negativo', 'Onboarding y acompañamiento'),
  ('K025', '2026-09-15', null, 'App Store', 5, 'Me encanta poder entrenar 20 minutos en la casa antes del trabajo.', 'Positivo', 'Resultados y hábito'),
  ('K026', '2026-08-03', null, 'Google Play', 1, 'Tercera vez que escribo por lo mismo: la aplicación se cierra. Si no lo arreglan este mes cancelo.', 'Negativo', 'Estabilidad técnica'),
  ('K027', '2026-01-13', 'C1001', 'Chat de soporte', null, 'Me inscribí y no supe por dónde empezar. Hay demasiadas clases y ninguna guía.', 'Negativo', 'Onboarding y acompañamiento'),
  ('K028', '2026-09-09', null, 'Google Play', 1, 'Para cancelar toca escribir a soporte y esperar. Inscribirse toma un minuto, cancelar tres días.', 'Negativo', 'Cancelación y pausa'),
  ('K029', '2026-08-03', null, 'Google Play', 1, 'Tercera vez que escribo por lo mismo: la aplicación se cierra. Si no lo arreglan este mes cancelo.', 'Negativo', 'Estabilidad técnica'),
